{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Ef fi cacy and safety of tocilizumab in COVID-19 patients: a living systematic review and meta-analysis, fi rst update",
      "reason": "The title explicitly states it is \"a living systematic review and meta-analysis,\" identifying the report as a systematic review."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Ef fi cacy and safety of tocilizumab in COVID-19 patients: a living systematic review and meta-analysis, fi rst update",
      "reason": "The title provides the key review focus and key elements: intervention \"tocilizumab\" and population \"COVID-19 patients\" (assessing \"efficacy and safety\")."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Ef fi cacy and safety of tocilizumab in COVID-19 patients: a living systematic review and meta-analysis, fi rst update",
      "reason": "The title includes relevant supplementary information indicating living-review status (\"living\") and update status (\"first update\"), and that it includes meta-analysis."
    }
  ],
  "confidence": 78
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "As of October 2020, cumulative moderate-certainty evidence from randomized controlled trials (RCTs) showed that the IL-6 receptor antagonist tocilizumab reduces the risk of mechanical ventilation in hospitalized COVID-19 patients, without affecting short-term mortality [1].",
      "reason": "The current state of knowledge is described (moderate-certainty evidence; effects on mechanical ventilation and short-term mortality), but important uncertainties are not explicitly reported in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "This report is the fi rst update of our living systematic review assessing the ef fi - cacy and safety of tocilizumab in COVID-19 patients [1].",
      "reason": "Conducting an update is stated (first update of a living systematic review), but the retrieved evidence does not clearly explain the broader importance/need for the review (e.g., why an updated review is necessary in the context of decision-making or emerging uncertainty)."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "This report is the fi rst update of our living systematic review assessing the ef fi - cacy and safety of tocilizumab in COVID-19 patients [1].",
      "reason": "A need for the current review as an update of an existing review is explicitly provided (\"first update\" of the authors’ living systematic review) with citation to the previous review ([1])."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence mentions that tocilizumab is an IL-6 receptor antagonist, but it does not briefly describe the proposed mechanism of action in the context required for the rationale item."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "There is no logic model or discussion of hypothesised relationships between intervention components and outcomes in the retrieved evidence."
    }
  ],
  "confidence": 62
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Objectives: Cytokine release syndrome with elevated interleukin-6 (IL-6) levels is associated with multiorgan damage and death in severe coronavirus disease 2019 (COVID-19). Our objective was to update the data in a living systematic review of the literature concerning the ef fi cacy and toxicity of the IL-6 receptor antagonist tocilizumab in COVID-19 patients.",
      "reason": "The review objective is explicitly stated in the abstract (to update data on efficacy and toxicity of tocilizumab in COVID-19 patients)."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "The participants were hospitalized COVID-19 patients, and intervention was tocilizumab versus placebo or standard of care.",
      "reason": "The planned comparisons for an intervention-effect review are explicitly stated with a PICO-like structure: hospitalized COVID-19 patients (P) and tocilizumab versus placebo/standard of care (I/C)."
    }
  ],
  "confidence": 86
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "table_0",
      "quote": "Table 1 Characteristics of completed randomized controlled trials of tocilizumab for coronavirus disease 2019 (COVID-19) patients\n\n| RCT                                    | Design and setting                                                                    | Enrolment dates                         | Inclusion criteria a                                                                             | MV (%)   | Steroids (%) (TCZ)   | Steroids (%) (Control)   | Days to TCZ (TCZ) b Median (IQR) or mean (SD)   | ... | Composite of poor outcome                                                                                            | Follow-up duration for secondary infections   |",
      "reason": "The manuscript reports study characteristics used for eligibility (e.g., design and setting, enrolment dates, inclusion criteria, and follow-up duration/endpoints) in Table 1, but the evidence provided does not clearly specify all relevant question-framework components and follow-up requirements across all eligibility determinations for both RCTs and observational studies."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was retrieved specifying eligibility criteria for report characteristics such as dissemination year, language, and publication/report status."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not describe how exclusions were distinguished between 'outcomes were not measured' vs 'outcome results were not reported'."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Using available data from fi ve studies [2,3,5 e 7], we assessed the effect of steroids on the composite of mortality or mechanical ventilation in patients taking tocilizumab versus controls. The risk ratios for patients receiving steroids and those not receiving steroids were 0.87 (95%CI 0.68 e 1.12) and 0.99 (95% 0.85 e 1.16) respectively. Additionally, there was no interaction between the use of mechanical ventilation and the effect of tocilizumab on mortality based on data from three studies [2,6,7]. The risk ratios for patients receiving and those not receiving mechanical ventilation are 1.02 (95%CI 0.79 e 1.31) and 0.98 (95%CI 0.89 e 1.07), respectively.",
      "reason": "The evidence identifies synthesis groupings linked to comparisons (e.g., tocilizumab vs controls stratified by steroids use and by mechanical ventilation use, and outcomes such as the composite of mortality or mechanical ventilation)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "As several RCTs have been published since our initial review, and as per peer reviewers' and editor's recommendations, this update includes observational studies up to January 2021, and future updates will include only data from RCTs.",
      "reason": "A rationale is provided for a notable restriction/limitation on study eligibility (inclusion of observational studies up to a specified date and exclusion of future non-RCT data)."
    }
  ],
  "confidence": 62
}

