{
  "item_id": "PRISMA_2020_10a",
  "elements": [
    {
      "element_id": "prisma_2020_10a_e1",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "Only the REMAP-CAP and RECOVERY trials, with the majority of their patients on concomitant corticosteroids, showed lower 30-day mortality with tocilizumab use: RR 0.74 (95%CI 0.59 e 0.93) and 0.89 (95%CI 0.81 e 0.97), respectively. Seven RCTs, with 5391 patients, examined the effect of tocilizumab on risk of mechanical ventilation; pooled RR was 0.84 (95%CI 0.76 e 0.93), I 2 0%, with a corresponding number needed to treat of 20 (95%CI 14.3 e 33.3). Eight RCTs, with 5340 patients, examined the effect of tocilizumab on a composite of poor outcome; pooled RR was 0.82 (95%CI 0.76 e 0.90, I 2 3%). Data from the RCTs showed a lower risk of infections and no higher risk of serious adverse events with tocilizumab: pooled RR 0.67 (95%CI 0.45 e 0.99, eight RCTs) and 0.85 (95%CI 0.63 e 1.16, seven RCTs), respectively.",
      "reason": "The evidence clearly identifies multiple outcome domains (mortality, mechanical ventilation, composite poor outcome, infections, serious adverse events) but does not explicitly state that all outcome domains sought are comprehensively listed and defined in a methods/data-items sense."
    },
    {
      "element_id": "prisma_2020_10a_e2",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "Eight RCTs, with 5340 patients, examined the effect of tocilizumab on a composite of poor outcome; pooled RR was 0.82 (95%CI 0.76 e 0.90, I 2 3%) (Fig. 1C). The de fi nition of this composite outcome in each trial is summarized in Table 1.",
      "reason": "A time frame for measurement is not explicitly specified here; however, the included trials’ outcome follow-up durations/days appear in Table 1 (e.g., day 30, day 28, 60 days), indicating time frames exist at the trial level rather than being clearly specified per outcome-domain measurement time in methods."
    },
    {
      "element_id": "prisma_2020_10a_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No statement was found describing whether all compatible results within each outcome domain were sought."
    },
    {
      "element_id": "prisma_2020_10a_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "Because there is no evidence provided about whether all compatible results were sought (and therefore no indication that selection was necessary), the conditional process for selecting results is not applicable based on the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_10a_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No report was found describing changes to outcome-domain inclusion/definitions/importance with rationales."
    },
    {
